def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0

    alive = []
    prev_bids = []
    desperate_count = 0
    rich_count = 0

    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            if opp.get('budget', 0) >= 120:
                rich_count += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))

    if len(alive) == 0:
        return min(budget, 18.0)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_pressure = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_pressure < 0:
        supply_pressure = 0.0
    if supply_pressure > 1:
        supply_pressure = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.55
    if no_water >= 2:
        urgency += 1.0
    elif no_water >= 1:
        urgency += 0.45

    if supply <= 17:
        urgency += 0.45
    elif supply <= 19:
        urgency += 0.2

    if day >= 8:
        urgency += 0.15

    if desperate_count >= 2:
        urgency += 0.2

    if budget < 70:
        urgency -= 0.2

    if urgency < 0:
        urgency = 0.0

    if highest_prev >= 115:
        pressure_bid = highest_prev + 1.0
    elif highest_prev >= 100:
        pressure_bid = highest_prev + 2.0
    elif highest_prev > 0:
        pressure_bid = max(72.0, highest_prev + 3.0)
    else:
        pressure_bid = 56.0

    conserve_bid = 18.0 + 18.0 * supply_pressure
    moderate_bid = 42.0 + 18.0 * supply_pressure
    assertive_bid = max(pressure_bid, 64.0 + 18.0 * supply_pressure)
    emergency_bid = max(pressure_bid, 92.0 + 10.0 * supply_pressure)

    if urgency >= 1.4:
        bid = emergency_bid
    elif urgency >= 0.75:
        bid = assertive_bid
    elif urgency >= 0.3:
        bid = moderate_bid
    else:
        bid = conserve_bid

    if avg_prev >= 105 and urgency < 0.75 and hp >= 5 and no_water == 0:
        bid = min(bid, 28.0 + 10.0 * supply_pressure)

    if rich_count >= 3 and supply <= 17 and urgency >= 0.75:
        bid += 4.0

    max_safe = budget
    if hp >= 6 and no_water == 0:
        max_safe = min(max_safe, budget * 0.55)
    elif hp >= 4:
        max_safe = min(max_safe, budget * 0.75)

    if urgency >= 1.4:
        max_safe = budget

    bid = min(bid, max_safe)
    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(bid)

