def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive = []
    for oid, o in opponents_status.items():
        try:
            if o.get('alive', False):
                alive.append((oid, o))
        except Exception:
            continue

    if not alive:
        # No opponents alive: spend enough to secure water if possible, but don't overspend.
        return min(budget, DAILY_SALARY * 0.4)

    # Extract yesterday bids from immediate previous_trace only.
    prev_bids = []
    for _, o in alive:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate opponent aggressiveness.
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        avg_prev_bid = sum(prev_bids) / float(len(prev_bids))
    else:
        highest_prev_bid = 0.0
        avg_prev_bid = 0.0

    # Base aggressiveness: undercut typical high bids while maintaining survival.
    # Target bid is a fraction of yesterday's average/high.
    if hp <= 2 or no_water_days >= 2:
        frac = 0.85
    elif hp <= 4:
        frac = 0.75
    else:
        frac = 0.65

    # Use average as main anchor; if empty, use a conservative fraction of DAILY_SALARY.
    if avg_prev_bid > 0:
        target = avg_prev_bid * frac
    else:
        target = DAILY_SALARY * 0.55

    # If yesterday's highest bid was extremely high, cap to avoid overpaying; still bid enough to compete.
    # Aim to be below the highest by a small margin.
    if highest_prev_bid > 0:
        target = min(target, highest_prev_bid * 0.92)

    # Supply-aware adjustment: with higher supply, competition should be less intense.
    # Normalize supply within [MIN_SUPPLY, MAX_SUPPLY].
    if MAX_SUPPLY > MIN_SUPPLY:
        s_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
        if s_norm < 0.0:
            s_norm = 0.0
        if s_norm > 1.0:
            s_norm = 1.0
    else:
        s_norm = 0.5

    # Higher supply -> slightly lower bid; lower supply -> slightly higher bid.
    # s_norm=1 => multiply by 0.92; s_norm=0 => multiply by 1.08
    supply_mult = 1.08 - 0.16 * s_norm
    target *= supply_mult

    # Ensure we never bid above budget.
    # Also, prevent bidding too low when HP is critical.
    min_floor = 0.0
    if hp <= 2:
        min_floor = DAILY_SALARY * 0.75
    elif hp <= 4:
        min_floor = DAILY_SALARY * 0.55
    else:
        min_floor = DAILY_SALARY * 0.35

    target = max(target, min_floor)
    bid = min(budget, target)

    # If budget is extremely low, bid whatever remains (can't do better than survival).
    if bid < 0.0:
        bid = 0.0
    return bid
